-- Battle pet compatibility data and koKR localization bundle.
-- Sources: MOPPREMIUM world database and the normalized Build_MOP_Repack koKR database.
-- This patch is intentionally idempotent because Update-Database.ps1 reapplies local patches.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `battlepet_template` (
  `SpecieID` int unsigned NOT NULL DEFAULT '0',
  `BreedMask` int unsigned NOT NULL DEFAULT '0',
  `Quality` tinyint unsigned NOT NULL DEFAULT '0',
  `Level` tinyint unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`SpecieID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `battlepet_npc_team_member` (
  `NpcID` int unsigned NOT NULL DEFAULT '0',
  `Species` int unsigned NOT NULL DEFAULT '0',
  `Level` tinyint unsigned NOT NULL DEFAULT '1',
  `Quality` tinyint unsigned NOT NULL DEFAULT '2',
  `Breed` tinyint unsigned NOT NULL DEFAULT '3',
  `DisplayID` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`NpcID`,`Species`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Pet Battle NPC trainer teams (compatibility/reference data)';

CREATE TABLE IF NOT EXISTS `battlepet_pvp_position` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `mapId` int unsigned NOT NULL DEFAULT '0',
  `first_x` float NOT NULL DEFAULT '0',
  `first_y` float NOT NULL DEFAULT '0',
  `first_z` float NOT NULL DEFAULT '0',
  `second_x` float NOT NULL DEFAULT '0',
  `second_y` float NOT NULL DEFAULT '0',
  `second_z` float NOT NULL DEFAULT '0',
  `origin_x` float NOT NULL DEFAULT '0',
  `origin_y` float NOT NULL DEFAULT '0',
  `origin_z` float NOT NULL DEFAULT '0',
  `facing` float NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

